import pandas as pd

frame = pd.DataFrame(
    {"time": pd.to_datetime(["2024-01-01 00:15", "2024-01-01 00:45", "2024-01-01 01:10"]), "value": [2, 4, 3]}
)
result = frame.resample("h", on="time")["value"].mean()
print(result)

