import pandas as pd

quotes = pd.DataFrame({
    "time": pd.to_datetime(["2024-01-01 09:00", "2024-01-01 09:05"]),
    "price": [100, 101],
})
trades = pd.DataFrame({
    "time": pd.to_datetime(["2024-01-01 09:02", "2024-01-01 09:07"]),
    "quantity": [10, 5],
})

result = pd.merge_asof(
    trades.sort_values("time"),
    quotes.sort_values("time"),
    on="time",
    direction="backward",
)
print(result)
